"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState, type SubmitEvent } from "react";
import { signup } from "@/lib/api/members/signup";
import { checkEmailDuplicate } from "@/lib/api/members/check-email-duplicate";
import { checkNicknameDuplicate } from "@/lib/api/members/check-nickname-duplicate";

// 이메일 형식 검사
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// 영문 대소문자, 숫자, 특수문자(!@#$%^&*)를 모두 포함해 8자 이상
const PASSWORD_REGEX =
  /^(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9])(?=.*[!@#$%^&*])[A-Za-z0-9!@#$%^&*]{8,}$/;

const DEFAULT_FORM = { email: "", nickname: "", password: "", passwordConfirm: "" };
type FormKey = keyof typeof DEFAULT_FORM;

const DEFAULT_DUPLICATE_CHECK = { isChecking: false, isAvailable: false };
type DuplicateCheckKey = "email" | "nickname";

export default function SignupForm() {
  const router = useRouter();
  const [form, setForm] = useState(DEFAULT_FORM);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [duplicateCheck, setDuplicateCheck] = useState({
    email: DEFAULT_DUPLICATE_CHECK,
    nickname: DEFAULT_DUPLICATE_CHECK,
  });

  const isEmailValid = EMAIL_REGEX.test(form.email.trim());
  const isNicknameValid = form.nickname.trim().length >= 2 && form.nickname.trim().length <= 12;
  const isPasswordValid = PASSWORD_REGEX.test(form.password);
  const isPasswordConfirmValid =
    form.passwordConfirm.length > 0 && form.password === form.passwordConfirm;

  const showEmailError = form.email.length > 0 && !isEmailValid;
  const showNicknameError = form.nickname.length > 0 && !isNicknameValid;
  const showPasswordError = form.password.length > 0 && !isPasswordValid;
  const showPasswordConfirmError = form.passwordConfirm.length > 0 && !isPasswordConfirmValid;

  const canSubmit =
    isEmailValid &&
    isNicknameValid &&
    isPasswordValid &&
    isPasswordConfirmValid &&
    duplicateCheck.email.isAvailable &&
    duplicateCheck.nickname.isAvailable;

  const handleChangeField = (key: FormKey, value: string) => {
    if (key === "email" || key === "nickname") {
      if (duplicateCheck[key].isChecking) return;
      setDuplicateCheck((prev) => ({ ...prev, [key]: DEFAULT_DUPLICATE_CHECK }));
    }
    setForm((prev) => ({ ...prev, [key]: value }));
  };

  const handleCheckDuplicate = async (key: DuplicateCheckKey) => {
    const isValid = key === "email" ? isEmailValid : isNicknameValid;
    if (!isValid || duplicateCheck[key].isChecking) return;

    const label = key === "email" ? "이메일" : "닉네임";
    setDuplicateCheck((prev) => ({ ...prev, [key]: { isChecking: true, isAvailable: false } }));

    try {
      const response =
        key === "email"
          ? await checkEmailDuplicate(form.email.trim())
          : await checkNicknameDuplicate(form.nickname.trim());
      const isAvailable = response.available;
      setDuplicateCheck((prev) => ({ ...prev, [key]: { ...prev[key], isAvailable } }));
      alert(isAvailable ? `사용할 수 있는 ${label}이에요.` : `이미 사용 중인 ${label}이에요.`);
    } catch {
      setDuplicateCheck((prev) => ({ ...prev, [key]: { ...prev[key], isAvailable: false } }));
      alert("중복 확인에 실패했어요. 다시 시도해 주세요.");
    } finally {
      setDuplicateCheck((prev) => ({ ...prev, [key]: { ...prev[key], isChecking: false } }));
    }
  };

  const handleSubmit = async (e: SubmitEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!canSubmit || isSubmitting) return;

    setIsSubmitting(true);
    try {
      const response = await signup({
        email: form.email.trim(),
        nickname: form.nickname.trim(),
        password: form.password,
      });
      alert(response.message);
      router.push("/login");
    } catch {
      alert("회원가입에 실패했어요. 다시 시도해 주세요.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const fieldClass =
    "h-12 w-full rounded-lg border border-[#e1e4ea] bg-white px-3 text-sm outline-none placeholder:text-gray-400 focus:border-[#4a60df]";
  const wrapClass =
    "flex items-center rounded-lg border border-[#e1e4ea] bg-white px-3 focus-within:border-[#4a60df]";
  const inputClass = "h-12 min-w-0 flex-1 text-sm outline-none placeholder:text-gray-400";
  const checkClass = "shrink-0 text-xs font-semibold text-[#3454e5] disabled:opacity-50";

  return (
    <>
      <form onSubmit={handleSubmit} noValidate className="space-y-4">
        <div>
          <label htmlFor="signup-email" className="mb-1 block text-sm font-semibold">이메일</label>
          <div className={wrapClass}>
            <input
              id="signup-email"
              type="email"
              value={form.email}
              disabled={duplicateCheck.email.isChecking}
              onChange={(e) => handleChangeField("email", e.target.value)}
              placeholder="name@example.com"
              className={inputClass}
            />
            <button
              type="button"
              disabled={!isEmailValid || duplicateCheck.email.isChecking}
              onClick={() => handleCheckDuplicate("email")}
              className={checkClass}
            >
              {duplicateCheck.email.isChecking ? "확인 중" : "중복 확인"}
            </button>
          </div>
          {showEmailError && <p className="mt-1 text-xs text-red-600">올바른 이메일 형식으로 입력해 주세요.</p>}
        </div>

        <div>
          <label htmlFor="signup-nickname" className="mb-1 block text-sm font-semibold">닉네임</label>
          <div className={wrapClass}>
            <input
              id="signup-nickname"
              type="text"
              value={form.nickname}
              disabled={duplicateCheck.nickname.isChecking}
              onChange={(e) => handleChangeField("nickname", e.target.value)}
              placeholder="2~12자"
              className={inputClass}
            />
            <button
              type="button"
              disabled={!isNicknameValid || duplicateCheck.nickname.isChecking}
              onClick={() => handleCheckDuplicate("nickname")}
              className={checkClass}
            >
              {duplicateCheck.nickname.isChecking ? "확인 중" : "중복 확인"}
            </button>
          </div>
          {showNicknameError && <p className="mt-1 text-xs text-red-600">닉네임은 2~12자로 입력해 주세요.</p>}
        </div>

        <div>
          <label htmlFor="signup-password" className="mb-1 block text-sm font-semibold">비밀번호</label>
          <input
            id="signup-password"
            type="password"
            value={form.password}
            onChange={(e) => handleChangeField("password", e.target.value)}
            placeholder="8자 이상"
            className={fieldClass}
          />
          <p className={`mt-1 text-xs ${showPasswordError ? "text-red-600" : "text-gray-500"}`}>
            영문 대문자·소문자·숫자·특수문자(!@#$%^&amp;*)를 포함해 8자 이상 입력해 주세요.
          </p>
        </div>

        <div>
          <label htmlFor="signup-password-confirm" className="mb-1 block text-sm font-semibold">비밀번호 확인</label>
          <input
            id="signup-password-confirm"
            type="password"
            value={form.passwordConfirm}
            onChange={(e) => handleChangeField("passwordConfirm", e.target.value)}
            placeholder="다시 입력"
            className={fieldClass}
          />
          {showPasswordConfirmError && <p className="mt-1 text-xs text-red-600">비밀번호가 일치하지 않아요.</p>}
        </div>

        <button
          type="submit"
          disabled={!canSubmit || isSubmitting}
          className="h-12 w-full rounded-lg bg-[#4a60df] text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-50"
        >
          {isSubmitting ? "가입 중" : "가입하기"}
        </button>
      </form>

      <p className="mt-4 text-center text-xs text-gray-500">
        이미 계정이 있나요?{" "}
        <Link href="/login" className="font-semibold text-[#3454e5]">로그인</Link>
      </p>
    </>
  );
}
